INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0, 905, 107611, "シズルさまにエリコさま、\nどうかされたのですか？", 19050041, 0, 1, 10, 11, 0.5, 0);
