INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0, 944, 107911, "はい、そこの流れてくるおねーさん\nたい焼きいかがかにゃ？", 19440025, 0, 1, 8, 11, 1, 0);
INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES ("", 944, 0, "", 19440026, "", "", "", 91, "", "");
