INSERT INTO `v1_f041a6a388116cf1e97b8560f62ecc248df4295ba6c2d00e2234484d5be99a9a` VALUES (0, 944, 107911, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 19440033, 0, 1, 10, 11, 1, 0);
